import { GoogleGenAI, Chat, Type } from "@google/genai";
import { Message, SocraticMode, AnalysisData } from "../types";
import { CRITICAL_THINKING_CRITERIA } from "../domainCriteria";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const CHAT_MODEL = "gemini-3-pro-preview";
const ANALYSIS_MODEL = "gemini-3-pro-preview";
const TUTOR_NAME = "Argos";

export const createChatSession = (mode: SocraticMode, topic: string, history: Message[] = []): Chat => {
  const ai = getAI();

  const systemInstruction = `
Tu es ${TUTOR_NAME}, un tuteur socratique bienveillant mais intellectuellement exigeant. Ton but est d'aider l'étudiant à muscler sa pensée critique sur : "${topic}".

OBJECTIF : Évaluer et encourager la capacité de l'étudiant à raisonner par lui-même.
CRITÈRES DE RÉFLEXION : ${CRITICAL_THINKING_CRITERIA.join(", ")}.

MÉTHODE :
- Tutoiement systématique et chaleureux.
- Ne donne JAMAIS la réponse. Aide l'étudiant à la trouver en le questionnant.
- Pose une seule question à la fois, courte, percutante et incitative.
- Au tout début, salue l'étudiant par son prénom de manière amicale.
- Mode ${mode === SocraticMode.TUTOR ? 'DÉFENSE : tu aides l\'étudiant à approfondir et solidifier sa propre argumentation' : 'CRITIQUE : tu proposes un court texte plausible contenant 2 ou 3 failles logiques que l\'étudiant doit identifier'}.

STRUCTURE DES RÉPONSES (À partir du 2ème message) :
Ajoute toujours ces balises pédagogiques en fin de message :
💡 Exigence : [Ce que j'attends de toi maintenant pour avancer]
🔍 Contrôle : [Le point logique ou le critère que nous surveillons ensemble]
  `.trim();

  return ai.chats.create({
    model: CHAT_MODEL,
    history: history.map(m => ({ 
      role: m.role, 
      parts: [{ text: m.text }] 
    })),
    config: { 
      systemInstruction, 
      temperature: 0.7 
    }
  });
};

export const sendMessage = async (chat: Chat, message: string) => {
  const response = await chat.sendMessage({ message });
  if (!response.text) {
    throw new Error("L'IA n'a pas renvoyé de texte. Possible blocage de sécurité ou erreur réseau.");
  }
  return { text: response.text };
};

export const generateAnalysis = async (
  transcript: Message[],
  topic: string,
  aiDeclaration: string
): Promise<AnalysisData> => {
  const ai = getAI();
  const transcriptText = transcript.map(m => `[${m.role === "user" ? "Étudiant" : TUTOR_NAME}]: ${m.text}`).join("\n");

  const prompt = `
Analyse avec précision ce dialogue socratique sur le sujet "${topic}".
L'étudiant déclare ceci sur son usage de l'IA : "${aiDeclaration}"

Transcription :
${transcriptText}

Évalue sur 100 les dimensions de pensée critique suivantes : ${CRITICAL_THINKING_CRITERIA.join(", ")}.
Identifie si l'étudiant a progressé dans son autonomie de pensée ou s'il s'est reposé sur des généralités.

Réponds au format JSON strict.
  `.trim();

  try {
    const response = await ai.models.generateContent({
      model: ANALYSIS_MODEL,
      contents: prompt,
      config: {
        temperature: 0.2,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            reasoningScore: { type: Type.INTEGER },
            clarityScore: { type: Type.INTEGER },
            skepticismScore: { type: Type.INTEGER },
            processScore: { type: Type.INTEGER },
            reflectionScore: { type: Type.INTEGER },
            disciplinaryDiscernmentScore: { type: Type.INTEGER },
            aiDeclarationCoherenceScore: { type: Type.INTEGER },
            keyStrengths: { type: Type.ARRAY, items: { type: Type.STRING } },
            weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
            aiUsageAnalysis: { type: Type.STRING }
          },
          required: ["summary", "reasoningScore", "aiDeclarationCoherenceScore", "keyStrengths", "weaknesses", "aiUsageAnalysis"]
        }
      }
    });

    const jsonStr = response.text?.trim() || "{}";
    return { ...JSON.parse(jsonStr), transcript, aiDeclaration };
  } catch (e) {
    console.error("Analysis Error:", e);
    return { 
      summary: "L'analyse automatique n'a pas pu être finalisée.", 
      reasoningScore: 0, clarityScore: 0, skepticismScore: 0, processScore: 0, reflectionScore: 0, 
      disciplinaryDiscernmentScore: 0, aiDeclarationCoherenceScore: 0, 
      keyStrengths: [], weaknesses: [], aiUsageAnalysis: "Erreur technique lors de l'audit.", 
      transcript, aiDeclaration 
    };
  }
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Send, StopCircle, RefreshCw, FileSignature, HelpCircle, AlertCircle } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { Chat } from "@google/genai";
import { Message, SessionConfig } from '../types';
import { sendMessage } from '../services/gemini';
import { GuideModal } from './GuideModal';

interface ChatViewProps {
  chatInstance: Chat | null;
  config: SessionConfig;
  messages: Message[];
  setMessages: React.Dispatch<React.SetStateAction<Message[]>>;
  onFinish: (aiDeclaration: string) => void;
}

export const ChatView: React.FC<ChatViewProps> = ({ chatInstance, config, messages, setMessages, onFinish }) => {
  const [inputText, setInputText] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showDeclarationModal, setShowDeclarationModal] = useState(false);
  const [showGuide, setShowGuide] = useState(false);
  const [declarationText, setDeclarationText] = useState('');
  const [lastActivityAt, setLastActivityAt] = useState<number>(Date.now());
  const [error, setError] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const isStarted = useRef(false);

  const initChat = useCallback(async () => {
    if (!chatInstance || isStarted.current) return;

    setIsLoading(true);
    setError(null);
    try {
      const res = await sendMessage(chatInstance, `Bonjour Argos, je suis ${config.studentName} et je suis prêt. Salue-moi par mon prénom et lance la session sur le sujet : ${config.topic}.`);
      const aiMsg: Message = {
        id: crypto.randomUUID(),
        role: 'model',
        text: res.text,
        timestamp: Date.now()
      };
      setMessages([aiMsg]);
      setLastActivityAt(Date.now());
      isStarted.current = true;
    } catch (e: any) { 
      console.error("Initialization error:", e);
      setError("Argos semble indisponible pour le moment. Vérifie ta connexion ou la configuration de l'API.");
    } finally { 
      setIsLoading(false); 
    }
  }, [chatInstance, config.studentName, config.topic, setMessages]);

  useEffect(() => {
    if (messages.length === 0 && chatInstance && !isStarted.current) {
      initChat();
    } else if (messages.length > 0) {
      isStarted.current = true;
    }
  }, [chatInstance, messages.length, initChat]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isLoading]);

  const handleSend = async () => {
    if (!inputText.trim() || !chatInstance || isLoading) return;

    setError(null);
    const now = Date.now();
    const reflectionTime = now - lastActivityAt;

    const userMsg: Message = {
      id: crypto.randomUUID(),
      role: 'user',
      text: inputText,
      timestamp: now,
      responseTimeMs: reflectionTime
    };

    setMessages(prev => [...prev, userMsg]);
    setInputText('');
    setIsLoading(true);

    try {
      const res = await sendMessage(chatInstance, userMsg.text);
      const aiMsg: Message = {
        id: crypto.randomUUID(),
        role: 'model',
        text: res.text,
        timestamp: Date.now()
      };
      setMessages(prev => [...prev, aiMsg]);
      setLastActivityAt(Date.now());
    } catch (error: any) {
      console.error("Send message error:", error);
      setError("Le message n'a pas été envoyé. Argos rencontre une difficulté technique.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex flex-col h-full bg-white relative">
      {showGuide && <GuideModal onClose={() => setShowGuide(false)} />}

      {showDeclarationModal && (
        <div className="absolute inset-0 z-50 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl shadow-2xl max-w-xl w-full p-8 animate-in fade-in zoom-in duration-300 border border-slate-100">
            <h2 className="text-xl font-black flex items-center gap-3 mb-6 uppercase tracking-tighter text-slate-900">
              <FileSignature className="text-indigo-600" /> Journal de bord IA
            </h2>
            <div className="bg-slate-50 p-4 mb-6 text-xs text-slate-600 rounded-xl leading-relaxed">
              Pour conclure cet audit, décris brièvement comment tu as utilisé l'IA (si c'est le cas) pour construire tes réponses ou tes recherches durant cette session.
            </div>
            <textarea value={declarationText} onChange={(e) => setDeclarationText(e.target.value)} placeholder="Usage de l'IA (prompts, outils...)" className="w-full h-32 p-4 bg-slate-50 border border-slate-200 rounded-xl mb-6 focus:ring-2 focus:ring-indigo-500 outline-none transition-all text-sm" />
            <div className="flex justify-end gap-3">
              <button onClick={() => setShowDeclarationModal(false)} className="px-5 py-2 text-[10px] font-black uppercase text-slate-400 tracking-widest hover:text-slate-600 transition-colors">Retour</button>
              <button onClick={() => onFinish(declarationText || "Aucun usage déclaré.")} className="px-6 py-2 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-indigo-600 transition-all shadow-lg">Générer l'Audit Final</button>
            </div>
          </div>
        </div>
      )}

      <header className="bg-white border-b px-6 py-4 flex justify-between items-center z-10">
        <div>
          <h2 className="text-sm font-black text-slate-900 uppercase tracking-tighter">{config.topic}</h2>
          <p className="text-[10px] text-slate-400 uppercase font-bold tracking-[0.2em]">{config.studentName} | {config.mode}</p>
        </div>
        <div className="flex gap-2">
          <button onClick={() => setShowGuide(true)} className="p-2 text-slate-300 hover:text-indigo-600 transition-colors"><HelpCircle size={20} /></button>
          <button onClick={() => setShowDeclarationModal(true)} className="flex items-center gap-2 px-4 py-2 bg-rose-600 text-white rounded-xl text-[10px] font-black tracking-widest shadow-md hover:bg-rose-700 transition-all active:scale-95 uppercase"><StopCircle size={14} /> Terminer</button>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto p-4 sm:p-8 space-y-8 scrollbar-hide">
        {messages.length === 0 && !isLoading && error && (
          <div className="flex flex-col items-center justify-center h-full space-y-4">
             <AlertCircle size={48} className="text-rose-500" />
             <p className="text-sm font-medium text-slate-600 text-center max-w-xs">{error}</p>
             <button 
               onClick={() => initChat()}
               className="px-6 py-2 bg-indigo-600 text-white rounded-xl text-[10px] font-black tracking-widest uppercase hover:bg-indigo-700 transition-all"
             >
               Réessayer de lancer la discussion
             </button>
          </div>
        )}

        {messages.map((msg) => (
          <div key={msg.id} className={`flex w-full ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] rounded-3xl px-6 py-5 shadow-sm border ${msg.role === 'user' ? 'bg-slate-900 text-white border-slate-800 rounded-br-none' : 'bg-white text-slate-800 border-slate-100 rounded-bl-none shadow-indigo-100/50'}`}>
              <div className={`prose prose-sm max-w-none ${msg.role === 'user' ? 'prose-invert' : 'prose-slate'}`}>
                <ReactMarkdown>{msg.text || "..."}</ReactMarkdown>
              </div>
              <div className="text-[9px] mt-4 opacity-40 uppercase font-black tracking-widest border-t border-current/10 pt-2">
                {msg.role === 'model' ? 'ARGOS AGENT' : config.studentName}
              </div>
            </div>
          </div>
        ))}

        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-indigo-50 border border-indigo-100 rounded-2xl px-5 py-4 flex items-center gap-3 shadow-sm animate-pulse">
              <RefreshCw className="animate-spin text-indigo-500" size={14} />
              <span className="text-[9px] text-indigo-600 font-black uppercase tracking-widest">Argos analyse tes mots...</span>
            </div>
          </div>
        )}

        {error && messages.length > 0 && (
          <div className="mx-auto max-w-md bg-rose-50 border border-rose-100 text-rose-800 px-4 py-3 rounded-2xl flex items-center gap-3">
            <AlertCircle size={18} className="shrink-0" />
            <p className="text-[10px] font-black uppercase tracking-widest">{error}</p>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="bg-white border-t p-4 sm:p-6">
        <div className="max-w-4xl mx-auto relative">
          <textarea 
            value={inputText} 
            onChange={(e) => setInputText(e.target.value)} 
            onKeyDown={handleKeyPress} 
            placeholder="Écris ton raisonnement ici..." 
            disabled={isLoading || (messages.length === 0 && !error)}
            className="w-full bg-slate-50 rounded-2xl pl-5 pr-14 py-4 border border-slate-200 focus:ring-2 focus:ring-indigo-500 focus:bg-white min-h-[64px] resize-none outline-none transition-all text-sm disabled:opacity-50" 
            rows={Math.min(5, inputText.split('\n').length || 1)} 
          />
          <button 
            onClick={handleSend} 
            disabled={!inputText.trim() || isLoading || (messages.length === 0)} 
            className="absolute right-3 bottom-3 p-2.5 bg-slate-900 text-white rounded-xl disabled:opacity-20 hover:bg-indigo-600 transition-all active:scale-90"
          >
            <Send size={20} />
          </button>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI, Chat, Type } from "@google/genai";
import { Message, SocraticMode, AnalysisData } from "../types";
import { CRITICAL_THINKING_CRITERIA } from "../domainCriteria";

const getAI = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey || apiKey === "undefined" || apiKey === "") {
    throw new Error("La clé d'API Gemini (API_KEY) est manquante. Vérifiez vos variables d'environnement sur Vercel/GitHub.");
  }
  return new GoogleGenAI({ apiKey });
};

const CHAT_MODEL = "gemini-3-pro-preview";
const ANALYSIS_MODEL = "gemini-3-pro-preview";
const TUTOR_NAME = "Argos";

export const createChatSession = (mode: SocraticMode, topic: string, history: Message[] = []): Chat => {
  const ai = getAI();

  const systemInstruction = `
Tu es ${TUTOR_NAME}, un tuteur socratique bienveillant mais intellectuellement exigeant. Ton but est d'aider l'étudiant à muscler sa pensée critique sur : "${topic}".

OBJECTIF : Évaluer et encourager la capacité de l'étudiant à raisonner par lui-même.
CRITÈRES DE RÉFLEXION : ${CRITICAL_THINKING_CRITERIA.join(", ")}.

MÉTHODE :
- Tutoiement systématique et chaleureux.
- Ne donne JAMAIS la réponse. Aide l'étudiant à la trouver en le questionnant.
- Pose une seule question à la fois, courte, percutante et incitative.
- Au tout début, salue l'étudiant par son prénom de manière amicale.
- Mode ${mode === SocraticMode.TUTOR ? 'DÉFENSE : tu aides l\'étudiant à approfondir et solidifier sa propre argumentation' : 'CRITIQUE : tu proposes un court texte plausible contenant 2 ou 3 failles logiques que l\'étudiant doit identifier'}.

STRUCTURE DES RÉPONSES (À partir du 2ème message) :
Ajoute toujours ces balises pédagogiques en fin de message :
💡 Exigence : [Ce que j'attends de toi maintenant pour avancer]
🔍 Contrôle : [Le point logique ou le critère que nous surveillons ensemble]
  `.trim();

  return ai.chats.create({
    model: CHAT_MODEL,
    history: history.map(m => ({ 
      role: m.role, 
      parts: [{ text: m.text }] 
    })),
    config: { 
      systemInstruction, 
      temperature: 0.7,
      // On évite de restreindre trop les tokens pour laisser la réflexion s'exprimer
    }
  });
};

export const sendMessage = async (chat: Chat, message: string) => {
  try {
    const response = await chat.sendMessage({ message });
    if (!response.text) {
      throw new Error("L'IA n'a pas renvoyé de texte (Possible filtrage de contenu ou quota dépassé).");
    }
    return { text: response.text };
  } catch (error: any) {
    console.error("Gemini API Error:", error);
    // Gestion spécifique des erreurs courantes
    if (error.message?.includes("API key not valid")) {
      throw new Error("Clé d'API invalide. Vérifiez la configuration.");
    }
    if (error.message?.includes("Model not found")) {
      throw new Error(`Le modèle ${CHAT_MODEL} n'est pas disponible dans votre zone ou pour cette clé.`);
    }
    throw error;
  }
};

