import { GoogleGenAI, Chat, Type } from "@google/genai";
import { Message, SocraticMode, AnalysisData, SocraticStrategy } from "../types";

const getAI = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey || apiKey === "undefined" || apiKey === "") {
    throw new Error("Clé API manquante");
  }
  return new GoogleGenAI({ apiKey });
};

const CHAT_MODEL = "gemini-3-flash-preview"; 
const ANALYSIS_MODEL = "gemini-3-pro-preview";
const TUTOR_NAME = "Argos";

export const createChatSession = (mode: SocraticMode, topic: string, history: Message[] = []): Chat => {
  const ai = getAI();

  const systemInstruction = `
Tu es ${TUTOR_NAME}, un tuteur socratique expert en pensée critique. Ton but est d'accompagner l'étudiant sur : "${topic}".

STRATÉGIES DISPONIBLES :
1. clarification (définir les termes)
2. test_necessite (vérifier si A implique forcément B)
3. contre_exemple (proposer un cas limite)
4. prediction (demander les conséquences d'une idée)
5. falsifiabilite (demander ce qui prouverait que l'idée est fausse)
6. mecanisme_causal (expliquer le "comment")
7. changement_cadre (changer d'échelle ou de point de vue)
8. compression (demander de résumer l'essentiel)
9. concession_controlee (admettre un point pour mieux tester le reste)

MÉTHODE :
- Tu recevras parfois une consigne interne de stratégie. Applique-la sans la nommer.
- Tutoiement. Une seule question courte par message.
- Mode ${mode === SocraticMode.TUTOR ? 'DÉFENSE' : 'CRITIQUE'}.
- Finis par :
💡 Exigence : [Action immédiate]
🔍 Contrôle : [Point de vigilance]
  `.trim();

  return ai.chats.create({
    model: CHAT_MODEL,
    history: history.map(m => ({ 
      role: m.role, 
      parts: [{ text: m.text }] 
    })),
    config: { systemInstruction, temperature: 0.7 }
  });
};

export const sendMessage = async (chat: Chat, message: string, strategy?: SocraticStrategy) => {
  const prompt = strategy ? `[STRATÉGIE INTERNE : ${strategy}] ${message}` : message;
  const response = await chat.sendMessage({ message: prompt });
  if (!response.text) throw new Error("Réponse vide");
  return { text: response.text };
};

export const generateAnalysis = async (
  transcript: Message[],
  topic: string,
  aiDeclaration: string
): Promise<AnalysisData> => {
  const ai = getAI();
  const transcriptText = transcript.map(m => `[${m.role === "user" ? "Étudiant" : TUTOR_NAME}]: ${m.text}`).join("\n");

  const prompt = `
En tant qu'expert en analyse cognitive, produis une TRACE D'APPRENTISSAGE du dialogue suivant sur "${topic}".

TRANSCRIPTION :
${transcriptText}

DÉCLARATION IA : "${aiDeclaration}"

CONSIGNES STRICTES :
1. AUCUNE NOTE, AUCUN CHIFFRE, AUCUN POURCENTAGE.
2. Ton neutre, analytique, factuel. Pas d'émojis.
3. Chaque observation doit être appuyée par des "evidenceQuotes" (citations courtes du transcript).
4. Statuts autorisés : non_traite, evoque, etaye, stress_teste.

FORMAT JSON REQUIS.
  `.trim();

  const traceSchema = {
    type: Type.OBJECT,
    properties: {
      status: { 
        type: Type.STRING, 
        description: "Statut qualitatif de progression",
        enum: ["non_traite", "evoque", "etaye", "stress_teste"] 
      },
      evidenceQuotes: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING },
        description: "Citations exactes du transcript prouvant ce statut"
      },
      expertObservation: { 
        type: Type.STRING,
        description: "Observation factuelle et lecture cognitive"
      },
      nextMove: { 
        type: Type.STRING,
        description: "L'action unique à mener au prochain tour"
      }
    },
    required: ["status", "evidenceQuotes", "expertObservation", "nextMove"]
  };

  const response = await ai.models.generateContent({
    model: ANALYSIS_MODEL,
    contents: prompt,
    config: {
      temperature: 0.1,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          summary: {
            type: Type.OBJECT,
            properties: {
              built: { type: Type.STRING },
              unstable: { type: Type.ARRAY, items: { type: Type.STRING } },
              nextStep: { type: Type.STRING }
            },
            required: ["built", "unstable", "nextStep"]
          },
          diagnostic: { type: Type.STRING },
          criteria: {
            type: Type.OBJECT,
            properties: {
              premises: traceSchema,
              evidence: traceSchema,
              bias: traceSchema,
              decentering: traceSchema,
              logic: traceSchema,
              integrity: traceSchema
            },
            required: ["premises", "evidence", "bias", "decentering", "logic", "integrity"]
          },
          argumentMap: {
            type: Type.OBJECT,
            properties: {
              claim: { type: Type.STRING },
              definitions: { type: Type.ARRAY, items: { type: Type.STRING } },
              assumptions: { type: Type.ARRAY, items: { type: Type.STRING } },
              evidence: { type: Type.ARRAY, items: { type: Type.STRING } },
              objections: { type: Type.ARRAY, items: { type: Type.STRING } },
              rebuttals: { type: Type.ARRAY, items: { type: Type.STRING } },
              falsifier: { type: Type.STRING }
            },
            required: ["claim", "definitions", "assumptions", "evidence", "objections", "rebuttals", "falsifier"]
          },
          deltas: { type: Type.ARRAY, items: { type: Type.STRING } },
          pivotalMoments: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                quote: { type: Type.STRING },
                analysis: { type: Type.STRING },
                impact: { type: Type.STRING, enum: ["positive", "negative", "neutral"] },
                whyItMatters: { type: Type.STRING }
              },
              required: ["quote", "analysis", "impact", "whyItMatters"]
            }
          },
          aiUsageAnalysis: { type: Type.STRING }
        },
        required: ["summary", "diagnostic", "criteria", "argumentMap", "deltas", "pivotalMoments", "aiUsageAnalysis"]
      } as any
    }
  });

  try {
    const jsonStr = response.text.trim().replace(/^```json/, '').replace(/```$/, '');
    return { ...JSON.parse(jsonStr), transcript, aiDeclaration };
  } catch (e) {
    throw new Error("Erreur de parsing de l'analyse Argos. Le modèle n'a pas respecté le format attendu.");
  }
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Send, StopCircle, RefreshCw, FileSignature, HelpCircle, AlertCircle } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { Chat } from "@google/genai";
import { Message, SessionConfig, SocraticStrategy } from '../types';
import { sendMessage } from '../services/gemini';
import { GuideModal } from './GuideModal';

export const ChatView: React.FC<{
  chatInstance: Chat | null;
  config: SessionConfig;
  messages: Message[];
  setMessages: React.Dispatch<React.SetStateAction<Message[]>>;
  onFinish: (aiDeclaration: string) => void;
}> = ({ chatInstance, config, messages, setMessages, onFinish }) => {
  const [inputText, setInputText] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showDeclarationModal, setShowDeclarationModal] = useState(false);
  const [showGuide, setShowGuide] = useState(false);
  const [declarationText, setDeclarationText] = useState('');
  const [lastStrategy, setLastStrategy] = useState<SocraticStrategy | undefined>();
  const [error, setError] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const STRATEGIES = Object.values(SocraticStrategy);

  const getNextStrategy = () => {
    const available = STRATEGIES.filter(s => s !== lastStrategy);
    return available[Math.floor(Math.random() * available.length)];
  };

  const handleSend = async (initialPrompt?: string) => {
    const text = initialPrompt || inputText;
    if (!text.trim() || !chatInstance || isLoading) return;

    const strategy = messages.length >= 2 ? getNextStrategy() : undefined;

    const userMsg: Message = {
      id: crypto.randomUUID(),
      role: 'user',
      text: initialPrompt ? "(Démarrage)" : text,
      timestamp: Date.now(),
    };

    if (!initialPrompt) setMessages(prev => [...prev, userMsg]);
    setInputText('');
    setIsLoading(true);
    setError(null);

    try {
      const res = await sendMessage(chatInstance, text, strategy);
      const aiMsg: Message = {
        id: crypto.randomUUID(),
        role: 'model',
        text: res.text,
        timestamp: Date.now(),
        strategy
      };
      setMessages(prev => [...prev, aiMsg]);
      setLastStrategy(strategy);
    } catch (e: any) {
      setError("Erreur de communication avec Argos.");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (messages.length === 0 && chatInstance) {
      handleSend(`Bonjour Argos, je suis ${config.studentName}. Lance la session sur : ${config.topic}.`);
    }
  }, [chatInstance]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isLoading]);

  return (
    <div className="flex flex-col h-full bg-slate-50 relative">
      {showGuide && <GuideModal onClose={() => setShowGuide(false)} />}

      {showDeclarationModal && (
        <div className="absolute inset-0 z-50 bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl shadow-2xl max-w-xl w-full p-8 animate-in fade-in zoom-in duration-300">
            <h2 className="text-xl font-black flex items-center gap-3 mb-6 uppercase text-slate-900">
              <FileSignature className="text-indigo-600" /> Journal d'Usage IA
            </h2>
            <textarea 
              value={declarationText} 
              onChange={(e) => setDeclarationText(e.target.value)} 
              placeholder="Comment as-tu utilisé l'IA pour tes recherches ?" 
              className="w-full h-32 p-4 bg-slate-50 border border-slate-200 rounded-xl mb-6 outline-none text-sm" 
            />
            <div className="flex justify-end gap-3">
              <button onClick={() => setShowDeclarationModal(false)} className="px-5 text-[10px] font-black uppercase text-slate-400">Retour</button>
              <button onClick={() => onFinish(declarationText || "Aucun usage déclaré.")} className="px-6 py-2 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest">Générer la trace</button>
            </div>
          </div>
        </div>
      )}

      <header className="bg-white border-b px-6 py-4 flex justify-between items-center shrink-0 shadow-sm z-10">
        <div className="overflow-hidden">
          <h2 className="text-sm font-black text-slate-900 uppercase truncate">{config.topic}</h2>
          <p className="text-[9px] text-slate-400 font-bold tracking-widest">{config.studentName.toUpperCase()}</p>
        </div>
        <button onClick={() => setShowDeclarationModal(true)} className="flex items-center gap-2 px-4 py-2 bg-rose-600 text-white rounded-xl text-[10px] font-black tracking-widest uppercase hover:bg-rose-700 transition-colors"><StopCircle size={14} /> Terminer</button>
      </header>

      <div className="flex-1 overflow-y-auto p-4 sm:p-8 space-y-6 scrollbar-hide">
        {messages.filter(m => !m.text.includes("Bonjour Argos")).map((msg) => (
          <div key={msg.id} className={`flex w-full animate-in fade-in slide-in-from-bottom-2 duration-300 ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[88%] sm:max-w-[75%] rounded-[1.8rem] px-6 py-5 shadow-md border transition-all ${
              msg.role === 'user' 
                ? 'bg-slate-900 text-white border-slate-800 rounded-tr-none' 
                : 'bg-white text-slate-800 border-slate-200 rounded-tl-none'
            }`}>
              <div className={`prose prose-sm max-w-none font-medium leading-relaxed ${
                msg.role === 'user' ? 'prose-invert prose-p:text-white' : 'prose-slate'
              }`}>
                <ReactMarkdown>{msg.text}</ReactMarkdown>
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-indigo-600 text-white px-5 py-3 rounded-2xl rounded-tl-none flex items-center gap-3 animate-pulse shadow-lg shadow-indigo-200">
              <RefreshCw className="animate-spin" size={14} />
              <span className="text-[10px] font-black uppercase tracking-widest">Argos analyse ton propos...</span>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="bg-white border-t p-4 sm:p-6 shrink-0 shadow-[0_-4px_20px_-10px_rgba(0,0,0,0.1)]">
        <div className="max-w-4xl mx-auto relative group">
          <textarea 
            value={inputText} 
            onChange={(e) => setInputText(e.target.value)} 
            onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
            placeholder="Réponds ici avec précision..." 
            className="w-full bg-slate-50 rounded-2xl pl-6 pr-16 py-5 border-2 border-slate-100 focus:border-indigo-500 focus:bg-white focus:ring-4 focus:ring-indigo-500/10 outline-none transition-all text-base font-medium resize-none shadow-inner" 
            rows={1}
          />
          <button 
            onClick={() => handleSend()} 
            disabled={!inputText.trim() || isLoading} 
            className="absolute right-3 bottom-3 p-3 bg-slate-900 text-white rounded-xl disabled:opacity-10 hover:bg-indigo-600 transition-all shadow-lg active:scale-90"
          >
            <Send size={20} />
          </button>
        </div>
      </div>
    </div>
  );
};

